create table public.epew_ffr_operations_records(restaurant_unit_id text not null references public.epew_restaurant_units(restaurant_unit_id),kind text not null check(kind in('gate','role','opening','daily','incident')),record_key text not null,version integer not null check(version>0),data jsonb not null,updated_at timestamptz not null default now(),primary key(restaurant_unit_id,kind,record_key));
create table public.epew_ffr_operations_revisions(id uuid primary key default gen_random_uuid(),restaurant_unit_id text not null,kind text not null,record_key text not null,version integer not null,previous_data jsonb,data jsonb not null,reason text not null,actor_user_id uuid,actor_email text not null,request_id uuid not null,request_input jsonb not null,created_at timestamptz not null default now(),unique(restaurant_unit_id,kind,record_key,version));
create index on public.epew_ffr_operations_revisions(actor_user_id,request_id);
create index on public.epew_ffr_operations_revisions(restaurant_unit_id,created_at desc);
alter table public.epew_ffr_operations_records enable row level security;
alter table public.epew_ffr_operations_revisions enable row level security;
revoke all on public.epew_ffr_operations_records,public.epew_ffr_operations_revisions from public,anon,authenticated;
grant select,insert,update on public.epew_ffr_operations_records to service_role;
grant select,insert on public.epew_ffr_operations_revisions to service_role;
create trigger immutable_ffr_operations_revisions before update or delete on public.epew_ffr_operations_revisions for each row execute function public.epew_ffr_workforce_append_only();
create function public.epew_ffr_operations_seed(p_unit text,p_actor uuid,p_email text,p_req uuid,p_reason text,p_input jsonb) returns void language plpgsql security invoker set search_path='' as $$
begin
 with seed(kind,key,data) as (
 select 'gate',key,jsonb_build_object('owner','Unassigned','status','pending','blocker','Pending preparation and evidence.','evidence',null,'attachment_id',null,'approval','pending','approval_evidence',null) from unnest(array['training','test_cook','simulation','soft_opening','grand_opening']) t(key)
 union all
 select 'role',key,jsonb_build_object('owner','Unassigned','employee_id',null,'backup',null,'duties',duties,'blocker','Assign a responsible person and complete the briefing.','evidence',null,'approval','pending','approval_evidence',null) from (values
 ('floor_manager','Coordinate the floor, queues, staffing and escalation.'),('kitchen_lead','Coordinate preparation, quality, food safety and kitchen timing.'),('pos_lead','Oversee POS readiness, payment issues and order accuracy.'),('expeditor','Match orders, check packaging and coordinate pickup/delivery handoffs.'),('membership_lead','Guide enrollment, verify member IDs and explain reward rules.'),('troubleshooter','Resolve customer issues and document follow-up.'),('inventory_runner','Monitor supplies and replenish stations during service.'),('media_contact','Coordinate approved media/community messaging and guest contact.')) t(key,duties)
 ), saved as (insert into public.epew_ffr_operations_records(restaurant_unit_id,kind,record_key,version,data) select p_unit,kind,key,1,data from seed on conflict do nothing returning *)
 insert into public.epew_ffr_operations_revisions(restaurant_unit_id,kind,record_key,version,data,reason,actor_user_id,actor_email,request_id,request_input) select restaurant_unit_id,kind,record_key,version,data,p_reason,p_actor,p_email,p_req,p_input from saved;
end$$;
revoke all on function public.epew_ffr_operations_seed(text,uuid,text,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.epew_ffr_operations_seed(text,uuid,text,uuid,text,jsonb) to service_role;
create function public.epew_ffr_operations_save(p_actor uuid,p_email text,p_unit text,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare rules jsonb:='{"gate":[{"key":"owner","label":"Owner","type":"text","required":true},{"key":"status","label":"Status","type":"select","required":true,"options":["pending","in_progress","blocked","ready_for_review","completed"]},{"key":"blocker","label":"Blocker","type":"textarea","required":false},{"key":"evidence","label":"Evidence / private file references","type":"textarea","required":false},{"key":"attachment_id","label":"Private evidence attachment UUID","type":"text","required":false},{"key":"approval","label":"Approval","type":"select","required":true,"options":["pending","approved","rejected"]},{"key":"approval_evidence","label":"Approval evidence","type":"textarea","required":false}],"role":[{"key":"owner","label":"Assigned person","type":"text","required":true},{"key":"employee_id","label":"Linked workforce employee ID","type":"text","required":false},{"key":"backup","label":"Backup / handoff","type":"text","required":false},{"key":"duties","label":"Responsibilities","type":"textarea","required":false},{"key":"blocker","label":"Blocker","type":"textarea","required":false},{"key":"evidence","label":"Briefing / readiness evidence","type":"textarea","required":false},{"key":"approval","label":"Approval","type":"select","required":true,"options":["pending","approved","rejected"]},{"key":"approval_evidence","label":"Approval evidence","type":"textarea","required":false}],"opening":[{"key":"opened_on","label":"Actual opening date (New York)","type":"date","required":true},{"key":"confirmed_by","label":"Confirmed by","type":"text","required":true},{"key":"evidence","label":"Opening confirmation evidence","type":"textarea","required":true}],"daily":[{"key":"business_date","label":"Business date (New York)","type":"date","required":true},{"key":"orders","label":"Completed paid orders","type":"number","required":false},{"key":"sales_cents","label":"Net food / beverage sales (USD cents, after refunds; exclude taxes / tips)","type":"number","required":false},{"key":"qualifying_member_meals","label":"Qualifying member meals","type":"number","required":false},{"key":"rewards_earned","label":"Free meals earned","type":"number","required":false},{"key":"rewards_redeemed","label":"Free meals redeemed","type":"number","required":false},{"key":"new_memberships","label":"New Food Fans Rewards memberships","type":"number","required":false},{"key":"orders_by_zip","label":"Orders by ZIP: [{\"zip\":\"11411\",\"orders\":3}] — use unknown for missing ZIP","type":"json","required":false},{"key":"best_sellers","label":"Best-selling items: [{\"menu_item_id\":\"ITEM-1\",\"name\":\"Item\",\"quantity\":3}]","type":"json","required":false},{"key":"food_waste","label":"Food waste quantities, units and reason; record verified none when applicable","type":"textarea","required":false},{"key":"labor_hours","label":"Actual labor hours","type":"number","required":false},{"key":"customer_complaints","label":"Customer complaint count","type":"number","required":false},{"key":"equipment_incidents","label":"Equipment incident count","type":"number","required":false},{"key":"delivery_problems","label":"Delivery problem count","type":"number","required":false},{"key":"inventory_alerts","label":"Inventory alert count","type":"number","required":false},{"key":"follow_up","label":"Incidents / actions and source references","type":"textarea","required":false},{"key":"source_evidence","label":"POS, reward ledger, time and waste report references","type":"textarea","required":true},{"key":"approval","label":"Review status","type":"select","required":true,"options":["pending","approved"]},{"key":"approval_evidence","label":"Daily review evidence","type":"textarea","required":false}],"incident":[{"key":"business_date","label":"Business date (New York)","type":"date","required":true},{"key":"category","label":"Category","type":"select","required":true,"options":["customer_complaint","equipment","delivery","inventory","food_waste"]},{"key":"description","label":"Issue details (avoid private customer details)","type":"textarea","required":true},{"key":"owner","label":"Owner","type":"text","required":true},{"key":"status","label":"Status","type":"select","required":true,"options":["open","in_progress","resolved"]},{"key":"action","label":"Action / resolution","type":"textarea","required":false},{"key":"evidence","label":"Evidence","type":"textarea","required":false}]}'::jsonb;k text:=p_input->>'kind';rk text:=p_input->>'record_key';d jsonb:=p_input->'data';expected integer:=(p_input->>'expected_version')::integer;req uuid:=(p_input->>'request_id')::uuid;old public.epew_ffr_operations_records;rev public.epew_ffr_operations_revisions;dependent public.epew_ffr_operations_records;field jsonb;v jsonb;item jsonb;ref text;opening jsonb;required_gates text[];dependency_keys text[];entry_count numeric;total numeric;counts text[]:=array['orders','sales_cents','qualifying_member_meals','rewards_earned','rewards_redeemed','new_memberships','customer_complaints','equipment_incidents','delivery_problems','inventory_alerts'];
begin
 if p_actor is null or p_email is null or not exists(select 1 from public.user_roles where role='administrator' and(user_id=p_actor or(user_id is null and lower(email)=lower(p_email)))) then raise exception using errcode='42501',message='Administrator required';end if;
 if req is null or coalesce(length(btrim(p_input->>'reason')),0) not between 1 and 4000 or not exists(select 1 from public.epew_restaurant_units where restaurant_unit_id=p_unit) then raise exception using errcode='22023',message='Invalid request';end if;
 perform pg_advisory_xact_lock(hashtextextended('ffr-operations:'||p_unit,0));
 select * into rev from public.epew_ffr_operations_revisions where actor_user_id=p_actor and request_id=req order by created_at limit 1;
 if found then if rev.restaurant_unit_id<>p_unit or rev.request_input<>p_input then raise exception using errcode='22023',message='Request ID reused';end if;return jsonb_build_object('saved',true,'replayed',true);end if;
 if p_input->>'action'='initialize' then perform public.epew_ffr_operations_seed(p_unit,p_actor,p_email,req,p_input->>'reason',p_input);return jsonb_build_object('saved',true);end if;
 if rules->k is null or rk is null or rk!~'^[A-Za-z0-9_.:-]{1,100}$' or expected is null or expected<0 or d is null or jsonb_typeof(d)<>'object' then raise exception using errcode='22023',message='Invalid record';end if;
 if exists(select 1 from jsonb_object_keys(d) key where not exists(select 1 from jsonb_array_elements(rules->k) f where f->>'key'=key)) then raise exception using errcode='22023',message='Unknown field';end if;
 for field in select value from jsonb_array_elements(rules->k) loop
 v:=d->(field->>'key');
 if coalesce((field->>'required')::boolean,false) and(v is null or v='null'::jsonb or v='""'::jsonb) then raise exception using errcode='22023',message='Required field';end if;
 if v is null or v='null'::jsonb or v='""'::jsonb then continue;end if;
 if field->>'type'='number' then if jsonb_typeof(v)<>'number' or((d->>(field->>'key'))::numeric<0 and field->>'key'<>'sales_cents') or(field->>'key'<>'labor_hours' and(d->>(field->>'key'))::numeric<>trunc((d->>(field->>'key'))::numeric)) then raise exception using errcode='22023',message='Invalid number';end if;
 elsif field->>'type'='json' then if jsonb_typeof(v)<>'array' or jsonb_array_length(v)>500 then raise exception using errcode='22023',message='Invalid breakdown';end if;
 else if jsonb_typeof(v)<>'string' or length(d->>(field->>'key'))>12000 then raise exception using errcode='22023',message='Invalid text';end if;
 if field->'options' is not null and not exists(select 1 from jsonb_array_elements_text(field->'options') opt where opt=d->>(field->>'key')) then raise exception using errcode='22023',message='Invalid option';end if;
 if field->>'type'='date' then perform(d->>(field->>'key'))::date;end if;end if;
 end loop;
 select * into old from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind=k and record_key=rk for update;
 if coalesce(old.version,0)<>expected then raise exception using errcode='40001',message='Record changed';end if;
 if k='gate' and rk not in('training','test_cook','simulation','soft_opening','grand_opening') or k='role' and rk not in('floor_manager','kitchen_lead','pos_lead','expeditor','membership_lead','troubleshooter','inventory_runner','media_contact') or k='opening' and rk<>'OPENING' then raise exception using errcode='22023',message='Invalid record identity';end if;
 if k in('gate','role','daily') and old.data->>'approval'='approved' and(old.data-'approval'-'approval_evidence') is distinct from(d-'approval'-'approval_evidence') then d:=d||'{"approval":"pending","approval_evidence":null}'::jsonb;end if;
 if k in('gate','role') and d->>'approval'='approved' then
 if lower(btrim(d->>'owner')) in('unassigned','pending','tba','') or nullif(btrim(d->>'blocker'),'') is not null or nullif(btrim(d->>'evidence'),'') is null or nullif(btrim(d->>'approval_evidence'),'') is null then raise exception using errcode='22023',message='Assigned owner, cleared blocker and evidence required';end if;
 if k='gate' then
 if d->>'status'<>'completed' then raise exception using errcode='22023',message='Completed gate required';end if;
 required_gates:=case rk when 'soft_opening' then array['training','test_cook','simulation'] when 'grand_opening' then array['training','test_cook','simulation','soft_opening'] else array[]::text[] end;
 if exists(select 1 from unnest(required_gates) g where not exists(select 1 from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind='gate' and record_key=g and data->>'approval'='approved')) then raise exception using errcode='22023',message='Prerequisite gates require approval';end if;
 if rk='grand_opening' and(select count(*) from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind='role' and data->>'approval'='approved')<>8 then raise exception using errcode='22023',message='All eight opening roles require approval';end if;
 end if;end if;
 if k='role' and nullif(d->>'employee_id','') is not null and not exists(select 1 from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='employee' and record_key=d->>'employee_id') then raise exception using errcode='22023',message='Employee not found in restaurant';end if;
 if k='gate' and nullif(d->>'attachment_id','') is not null and not exists(select 1 from public.epew_restaurant_work_files where restaurant_unit_id=p_unit and id=(d->>'attachment_id')::uuid) then raise exception using errcode='22023',message='Private evidence attachment required';end if;
 if k='opening' then
 if(d->>'opened_on')::date>(now() at time zone 'America/New_York')::date or nullif(btrim(d->>'confirmed_by'),'') is null or nullif(btrim(d->>'evidence'),'') is null then raise exception using errcode='22023',message='Actual opening confirmation required';end if;
 if not exists(select 1 from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind='gate' and record_key='soft_opening' and data->>'approval'='approved') then raise exception using errcode='22023',message='Soft opening approval required';end if;
 if old.data is not null and old.data->>'opened_on' is distinct from d->>'opened_on' and exists(select 1 from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind in('daily','incident')) then raise exception using errcode='22023',message='Opening date locked after operating records';end if;
 end if;
 if k in('daily','incident') then
 select data into opening from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind='opening' and record_key='OPENING';
 if opening is null or(d->>'business_date')::date<(opening->>'opened_on')::date or(d->>'business_date')::date>(now() at time zone 'America/New_York')::date then raise exception using errcode='22023',message='Confirmed opening and valid business date required';end if;
 end if;
 if k='daily' then
 if rk<>d->>'business_date' or rk!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception using errcode='22023',message='Daily record key must equal date';end if;
 if(d->>'orders')::numeric=0 and(d->>'sales_cents')::numeric>0 then raise exception using errcode='22023',message='Sales require orders';end if;
 if d->'orders_by_zip' is not null and d->'orders_by_zip'<>'null'::jsonb then
 total:=0;
 for item in select value from jsonb_array_elements(d->'orders_by_zip') loop
 if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'zip') is distinct from 'string' or item->>'zip'!~'^([0-9]{5}|unknown)$' or jsonb_typeof(item->'orders') is distinct from 'number' or(item->>'orders')::numeric<0 or(item->>'orders')::numeric<>trunc((item->>'orders')::numeric) or exists(select 1 from jsonb_object_keys(item) key where key not in('zip','orders')) then raise exception using errcode='22023',message='Invalid ZIP breakdown';end if;
 total:=total+(item->>'orders')::numeric;end loop;
 if(select count(*) from jsonb_array_elements(d->'orders_by_zip'))<>(select count(distinct x->>'zip') from jsonb_array_elements(d->'orders_by_zip') x) then raise exception using errcode='22023',message='Duplicate ZIP';end if;
 if nullif(d->>'orders','') is not null and total<>(d->>'orders')::numeric then raise exception using errcode='22023',message='ZIP totals must equal orders including unknown ZIP';end if;
 end if;
 if d->'best_sellers' is not null and d->'best_sellers'<>'null'::jsonb then
 for item in select value from jsonb_array_elements(d->'best_sellers') loop
 if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'menu_item_id') is distinct from 'string' or nullif(btrim(item->>'menu_item_id'),'') is null or jsonb_typeof(item->'name') is distinct from 'string' or nullif(btrim(item->>'name'),'') is null or jsonb_typeof(item->'quantity') is distinct from 'number' or(item->>'quantity')::numeric<0 or(item->>'quantity')::numeric<>trunc((item->>'quantity')::numeric) or exists(select 1 from jsonb_object_keys(item) key where key not in('menu_item_id','name','quantity')) then raise exception using errcode='22023',message='Invalid best-selling item';end if;end loop;
 end if;
 if d->>'approval'='approved' then
 foreach ref in array counts||array['labor_hours','food_waste','orders_by_zip','best_sellers'] loop if not(d?ref) or d->ref='null'::jsonb or d->ref='""'::jsonb then raise exception using errcode='22023',message='All daily metrics required for approval';end if;end loop;
 if nullif(btrim(d->>'approval_evidence'),'') is null then raise exception using errcode='22023',message='Daily approval evidence required';end if;
 end if;
 end if;
 if k='incident' and d->>'status'='resolved' and(nullif(btrim(d->>'action'),'') is null or nullif(btrim(d->>'evidence'),'') is null) then raise exception using errcode='22023',message='Resolution evidence required';end if;
 insert into public.epew_ffr_operations_records values(p_unit,k,rk,expected+1,d,clock_timestamp()) on conflict(restaurant_unit_id,kind,record_key) do update set version=excluded.version,data=excluded.data,updated_at=excluded.updated_at;
 insert into public.epew_ffr_operations_revisions(restaurant_unit_id,kind,record_key,version,previous_data,data,reason,actor_user_id,actor_email,request_id,request_input) values(p_unit,k,rk,expected+1,old.data,d,p_input->>'reason',p_actor,p_email,req,p_input);
 -- Material corrections withdraw approval and invalidate downstream launch approvals.
 if(old.data->>'approval'='approved' and d->>'approval' is distinct from 'approved') and k in('gate','role') then
 dependency_keys:=case when k='role' or rk='soft_opening' then array['grand_opening'] when rk in('training','test_cook','simulation') then array['soft_opening','grand_opening'] else array[]::text[] end;
 for dependent in select * from public.epew_ffr_operations_records where restaurant_unit_id=p_unit and kind='gate' and record_key=any(dependency_keys) and data->>'approval'='approved' for update loop
 v:=dependent.data||jsonb_build_object('approval','pending','approval_evidence',null,'status','ready_for_review','blocker','Prerequisite changed; renewed review required.');
 update public.epew_ffr_operations_records set data=v,version=dependent.version+1,updated_at=clock_timestamp() where restaurant_unit_id=p_unit and kind='gate' and record_key=dependent.record_key;
 insert into public.epew_ffr_operations_revisions(restaurant_unit_id,kind,record_key,version,previous_data,data,reason,actor_user_id,actor_email,request_id,request_input) values(p_unit,'gate',dependent.record_key,dependent.version+1,dependent.data,v,'Prerequisite changed: '||k||' '||rk||'. '||(p_input->>'reason'),p_actor,p_email,req,p_input);
 end loop;end if;
 return jsonb_build_object('saved',true,'version',expected+1);
end$$;
revoke all on function public.epew_ffr_operations_save(uuid,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.epew_ffr_operations_save(uuid,text,text,jsonb) to service_role;
select public.epew_ffr_operations_seed('FFR-001',null,'system:technical-assistant',gen_random_uuid(),'Samuel authorized five pending launch gates, eight grand-opening roles and daily operating records; October 30, 2026.','{"source":"Samuel sections 20–21 directive"}'::jsonb);
